const CACHE='albion-forge-v2';self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(["./","./manifest.webmanifest","./icon-192.png","./icon-512.png","./catalog/part-0.js","./catalog/part-1.js","./catalog/part-10.js","./catalog/part-11.js","./catalog/part-12.js","./catalog/part-13.js","./catalog/part-14.js","./catalog/part-15.js","./catalog/part-16.js","./catalog/part-17.js","./catalog/part-18.js","./catalog/part-19.js","./catalog/part-2.js","./catalog/part-20.js","./catalog/part-21.js","./catalog/part-22.js","./catalog/part-3.js","./catalog/part-4.js","./catalog/part-5.js","./catalog/part-6.js","./catalog/part-7.js","./catalog/part-8.js","./catalog/part-9.js"])));self.skipWaiting()});self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));self.addEventListener('fetch',e=>{if(new URL(e.request.url).origin!==self.location.origin)return;e.respondWith(fetch(e.request).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy))}return r}).catch(()=>caches.match(e.request)))})
